    /**
     * @param string $path
     * @param string $releases
     * @return string|null
     */
    private static function current(string $path, string $releases): ?string
    {
        if (! file_exists($path) && ! NativeBuildFiles::isLink($path)) {
            return null;
        }
        $target = realpath($path);
        if (! NativeBuildFiles::isLink($path) || $target === false
            || dirname($target) !== $releases || ! preg_match('/^[a-f0-9]{32}$/D', basename($target))
            || ! is_dir($target) || NativeBuildFiles::isLink($target)) {
            throw new \RuntimeException('Existing activation is not a managed release link.');
        }
        return $target;
    }

    /**
     * @param string $target
     * @param string $link
     * @return void
     */
    private static function link(string $target, string $link): void
    {
        if (file_exists($link) || NativeBuildFiles::isLink($link)) {
            throw new \RuntimeException('Activation staging link already exists.');
        }
        if (PHP_OS_FAMILY === 'Windows') {
            self::command(['powershell.exe', '-NoProfile', '-NonInteractive', '-Command',
                '$ErrorActionPreference="Stop"; New-Item -ItemType Junction -Path $env:EXFACE_INSTALL_LINK -Target $env:EXFACE_INSTALL_TARGET | Out-Null'],
                dirname($link), 30, ['EXFACE_INSTALL_LINK' => $link, 'EXFACE_INSTALL_TARGET' => $target]);
        } elseif (! symlink($target, $link)) {
            throw new \RuntimeException('Cannot create activation symlink.');
        }
    }

    /**
     * @param string $path
     * @return void
     */
    private static function removeLink(string $path): void
    {
        if (NativeBuildFiles::isLink($path)) {
            if (PHP_OS_FAMILY === 'Windows' ? ! rmdir($path) : ! unlink($path)) {
                throw new \RuntimeException('Cannot remove activation link.');
            }
        } elseif (file_exists($path)) {
            throw new \RuntimeException('Refusing to remove an ordinary activation path.');
        }
    }

    /**
     * @param string|null $source
     * @param string $destination
     * @return void
     */
    private static function overlay(?string $source, string $destination): void
    {
        self::ordinary($destination);
        if ($source !== null && file_exists($source)) {
            self::tree($source);
            if (! is_dir($source)) {
                throw new \RuntimeException('Copied settings must select directories.');
            }
            NativeBuildFiles::remove($destination);
            self::copy($source, $destination);
        } elseif (! is_dir($destination) && ! mkdir($destination, 0700, true)) {
            throw new \RuntimeException('Cannot prepare copied directory.');
        }
    }

    /**
     * @param string $source
     * @param string $destination
     * @return void
     */
    private static function copy(string $source, string $destination): void
    {
        if (is_dir($source)) {
            if (! is_dir($destination) && ! mkdir($destination, 0700, true)) {
                throw new \RuntimeException('Cannot copy local directory.');
            }
            foreach (new \FilesystemIterator($source) as $child) {
                self::copy($child->getPathname(), $destination . DIRECTORY_SEPARATOR . $child->getFilename());
            }
        } elseif (! copy($source, $destination) || ! chmod($destination, 0600)) {
            throw new \RuntimeException('Cannot copy local file.');
        }
    }

    /**
     * @param string $path
     * @return void
     */
    private static function tree(string $path): void
    {
        self::ordinary($path);
        if (is_dir($path)) {
            foreach (new \FilesystemIterator($path) as $child) {
                self::tree($child->getPathname());
            }
        } elseif (! is_file($path)) {
            throw new \RuntimeException('Special files are not supported.');
        }
    }

    /**
     * Rejects links/reparse points in every existing component.
     *
     * @param string $path
     * @return void
     */
    private static function ordinary(string $path): void
    {
        for ($part = $path; dirname($part) !== $part; $part = dirname($part)) {
            if (NativeBuildFiles::isLink($part)) {
                throw new \RuntimeException('Links are forbidden in installer data paths.');
            }
        }
        if (file_exists($path) && ! is_dir($path) && ! is_file($path)) {
            throw new \RuntimeException('Special files are forbidden.');
        }
    }

    /**
     * Validates package binding and the independent local root before any target writes.
     *
     * @param array $manifest
     * @param string $root
     * @return string
     */
    public static function resolveRoot(array $manifest, string $root): string
    {
