                || array_key_exists('installation_root', $host)) {
                throw new \RuntimeException('Invalid native package root binding.');
            }
            if ($root === '') {
                throw new \RuntimeException('This package requires explicit --root <existing absolute installation directory>; no target was changed.');
            }
        } elseif (! isset($host['installation_root']) || ! is_string($host['installation_root'])
            || $host['installation_root'] === '') {
            throw new \RuntimeException('Invalid authoritative host root.');
        }
        self::absoluteRoot($root);
        $resolved = realpath($root);
        if (! isset($host['installation_root_binding'])
            && self::normalize($host['installation_root']) !== self::normalize($resolved)) {
            throw new \RuntimeException('Explicit root does not match the authoritative host root.');
        }
        if (! isset($host['operating_system']) || ! is_string($host['operating_system'])
            || ! in_array($host['operating_system'], ['Windows', 'Linux', 'Unix'], true)
            || (PHP_OS_FAMILY === 'Windows') !== ($host['operating_system'] === 'Windows')) {
            throw new \RuntimeException('Package host operating system does not match this runtime.');
        }
        return $resolved;
    }

    private static function absoluteRoot(string $root): void
    {
        if (! preg_match(PHP_OS_FAMILY === 'Windows' ? '~^[A-Za-z]:[\\\\/]~' : '~^/~', $root)
            || preg_match('~[\x00-\x1f]|(?:^|[\\\\/])\.\.?(?:[\\\\/]|$)~', $root)
            || ! is_dir($root) || dirname($root) === $root) {
            throw new \RuntimeException('Root must be an existing absolute installation directory, not a filesystem root.');
        }
        self::ordinary($root);
    }

    /**
     * @param string $path
     * @return string
     */
    private static function normalize(string $path): string
    {
        $path = rtrim(str_replace(['/', '\\'], DIRECTORY_SEPARATOR, $path), DIRECTORY_SEPARATOR);
        return PHP_OS_FAMILY === 'Windows' ? strtolower($path) : $path;
    }

    /**
     * @param string $path
     * @param array $data
     * @return void
     */
    private static function saveJournal(string $path, array $data): void
    {
        self::ordinary($path . '.new');
        self::write($path . '.new', json_encode($data, JSON_THROW_ON_ERROR));
        if (! rename($path . '.new', $path)) {
            throw new \RuntimeException('Cannot persist recovery journal.');
        }
    }

    /**
     * @param string $path
     * @param string $contents
     * @return void
     */
    private static function write(string $path, string $contents): void
    {
        self::ordinary($path);
        if (file_put_contents($path, $contents) !== strlen($contents) || ! chmod($path, 0600)) {
            throw new \RuntimeException('Cannot write private installer metadata.');
        }
    }

    /**
